@startuml

class University {
  + totalEmployees : int
}

class Faculty {
  + name : string
}

class Institute {
  + name : string
  + address : string
}

class Employee {
  + socialSecurityNumber : string
  + name : string
  + emailAddress : string
}

class ResearchStaff extends Employee {}

class AdministrativeStaff extends Employee {}

class ResearchAssistant extends ResearchStaff {
  + fieldOfResearch : string
}

class Lecturer extends ResearchAssistant {}

class Project {
  + name : string
  + startDate : date
  + endDate : date
  + hours : int
}

class Course {
  + id : int
  + name : string
  + weeklyDuration : int
}

University "1" -- "*" Faculty
Faculty "1" -- "*" Institute
Faculty "1" --> "1" Employee : dean
University "1" -- "*" Employee
ResearchAssistant "*" -- "1..*" Institute
ResearchAssistant "1" -- "*" Project
Lecturer "1" -- "*" Course

@enduml

